def copy_site_chrome(apps, schema_editor):
    """0.3 stored one header + one footer per site (SiteChrome). Turn each into a reusable
    SiteHeader / SiteFooter; the default site's (else the first) become the site defaults.
    Uses the historical models (apps.get_model), as data migrations must."""
    import json

    SiteChrome = apps.get_model("prblm_builder_blocks", "SiteChrome")
    targets = {
        "header": apps.get_model("prblm_builder_blocks", "SiteHeader"),
        "footer": apps.get_model("prblm_builder_blocks", "SiteFooter"),
    }
    has_default = {"header": False, "footer": False}
    rows = SiteChrome.objects.select_related("site").order_by("-site__is_default_site", "pk")
    for row in rows:
        site_label = row.site.site_name or row.site.hostname
        for kind, Model in targets.items():
            raw = list(getattr(row, kind).raw_data)
            if not raw:
                continue
            Model.objects.create(
                name=f"{site_label} {kind}",
                is_default=not has_default[kind],
                content=json.dumps(raw),
            )
            has_default[kind] = True


